    );

    let state_after = shard
        .run_state_get(run)
        .ok_or("run must remain active after rejected retry drive")?;
    assert_eq!(state_after.action_attempts.get(1).copied(), Some(2));
    assert_eq!(state_after.frame.pc(), StepIdx::new(1));
